#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; set -a; . "$root/.env.example"; set +a
host="$(aws rds describe-db-instances --db-instance-identifier "$LOCAL_RDS_INSTANCE_ID" --endpoint-url "$AWS_ENDPOINT_URL" --query 'DBInstances[0].Endpoint.Address' --output text)"; port="$(aws rds describe-db-instances --db-instance-identifier "$LOCAL_RDS_INSTANCE_ID" --endpoint-url "$AWS_ENDPOINT_URL" --query 'DBInstances[0].Endpoint.Port' --output text)"
PGPASSWORD="$LOCAL_RDS_PASSWORD" psql --host "$host" --port "$port" --username "$LOCAL_RDS_USERNAME" --dbname "$LOCAL_RDS_DATABASE" --command "SELECT * FROM archive.current_version_display; SELECT * FROM archive.current_active_closure; SELECT title_code,title_text,language_code,variant_code FROM archive.version_title ORDER BY title_code; SELECT department_code,name FROM archive.department; SELECT series_code,name FROM archive.series; SELECT record_reference FROM archive.record; SELECT representation_code,representation_type FROM archive.representation; SELECT file_name,relative_path FROM archive.file; SELECT consignment_reference,received_at FROM archive.consignment; SELECT version_id,default_title_code,valid_from,valid_to,is_current,changed_by_name,change_reason FROM history.version ORDER BY valid_from; SELECT version_title_id,title_code,title_text,valid_from,valid_to,is_current,changed_by_name,change_reason FROM history.version_title WHERE version_title_id='10000000-0000-4000-8000-000000000013' ORDER BY valid_from; SELECT closure_id,status,valid_from,valid_to,is_current,changed_by_name,change_reason FROM history.closure ORDER BY valid_from; SELECT entity_type,entity_key,change_type,outcome,processing_status,changes,changed_by_name,change_reason,source_system,changed_at FROM archive.metadata_change_event ORDER BY processed_at;"
